    data,
    rc,
    side = "Two-sided",
    a = "0.05") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("FishersChiSquareTest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rc)) rc <- jmvcore::resolveQuo(jmvcore::enquo(rc))
